/** Daily egg-radar manual refresh helpers (local calendar day, escalating cost). */

import type { GameRuntime } from '../types/game.js';

export const EGG_RADAR_FREE_REFRESHES_PER_DAY = 3;
export const EGG_RADAR_PAID_REFRESH_BASE_COST = 10_000;

export function getLocalCalendarDayKey(date: Date = new Date()): string {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
}

/** Cost for the next manual refresh after `refreshesUsedToday` refreshes already done today. */
export function getEggRadarRefreshCost(refreshesUsedToday: number): number {
    const used = Math.max(0, Math.floor(Number(refreshesUsedToday) || 0));
    if (used < EGG_RADAR_FREE_REFRESHES_PER_DAY) return 0;
    const paidIndex = used - EGG_RADAR_FREE_REFRESHES_PER_DAY;
    return EGG_RADAR_PAID_REFRESH_BASE_COST * Math.pow(2, paidIndex);
}

export function resetEggRadarDailyIfNeeded(
    state: Record<string, unknown>,
    dayKey: string = getLocalCalendarDayKey()
): void {
    if (!state || typeof state !== 'object') return;
    const savedDay = typeof state.refreshDayKey === 'string' ? state.refreshDayKey : '';
    if (savedDay !== dayKey) {
        state.refreshDayKey = dayKey;
        state.refreshCountToday = 0;
    }
    if (typeof state.refreshCountToday !== 'number' || !Number.isFinite(state.refreshCountToday)) {
        state.refreshCountToday = 0;
    }
}

/** True when mastery tier layout changed (upgrade), not on first boot or page reload. */
export function shouldForceRadarLayoutRefresh(prevLayoutKey: string, nextLayoutKey: string): boolean {
    const prev = typeof prevLayoutKey === 'string' ? prevLayoutKey : '';
    const next = typeof nextLayoutKey === 'string' ? nextLayoutKey : '';
    return prev.length > 0 && prev !== next;
}

/** Selected names to persist, filtered to current candidates. */
export function radarSelectedListForSave(
    state: { selected?: string | null; selectedList?: string[] } | null | undefined,
    candidates: string[]
): string[] {
    if (!state || candidates.length === 0) return [];
    const candSet = new Set(candidates);
    let list = Array.isArray(state.selectedList)
        ? state.selectedList.filter((n) => typeof n === 'string' && candSet.has(n))
        : [];
    if (list.length === 0 && typeof state.selected === 'string' && candSet.has(state.selected)) {
        list = [state.selected];
    }
    return list;
}

export function createEmptyEggRadarState(): Record<string, unknown> {
    return {
        candidates: [] as string[],
        selected: null as string | null,
        selectedList: [] as string[],
        refreshDayKey: getLocalCalendarDayKey(),
        refreshCountToday: 0,
    };
}

/** Full hatchable egg pool for radar picks (includes owned species — egg radar targets hatch weight). */
export function buildEggRadarPickPool(eggPool: string[]): string[] {
    if (!Array.isArray(eggPool) || eggPool.length === 0) return [];
    return eggPool.slice();
}

/** Shuffle egg pool and return up to eggCandidateCount names. */
export function pickEggRadarCandidates(eggPool: string[], eggCandidateCount: number): string[] {
    return pickRadarCandidatesFromPool(buildEggRadarPickPool(eggPool), eggCandidateCount);
}

/** Priority pool for zone radar picks: not owned → no shiny → full species list. */
export function buildRadarPickPool(
    game: Pick<GameRuntime, 'pokedex'> | null | undefined,
    species: string[]
): string[] {
    if (!Array.isArray(species) || species.length === 0) return [];
    const ownedEntries = Object.values(game?.pokedex ?? {}) as Array<{ name?: string; hasShiny?: boolean }>;
    const ownedNames = new Set(
        ownedEntries.map((e) => e.name).filter((n): n is string => typeof n === 'string' && n.length > 0)
    );
    const shinyNames = new Set(
        ownedEntries
            .filter((e) => e.hasShiny && typeof e.name === 'string')
            .map((e) => e.name as string)
    );
    const notOwned = species.filter((n) => !ownedNames.has(n));
    if (notOwned.length > 0) return notOwned.slice();
    const noShiny = species.filter((n) => ownedNames.has(n) && !shinyNames.has(n));
    if (noShiny.length > 0) return noShiny.slice();
    return species.slice();
}

export function getRadarCandidateCap(pickPool: string[], eggCandidateCount: number): number {
    const n = Math.max(1, Math.floor(Number(eggCandidateCount) || 0));
    return Math.min(n, pickPool.length);
}

/** True when saved egg-radar candidates should be repicked (stale count, invalid species). */
export function eggRadarCandidatesNeedRepick(
    curCandidates: string[],
    eggPool: string[],
    pickPool: string[],
    eggCandidateCount: number
): boolean {
    if (!Array.isArray(curCandidates) || curCandidates.length === 0) return true;
    const cap = getRadarCandidateCap(pickPool, eggCandidateCount);
    if (curCandidates.length < cap) return true;
    const eggSet = new Set(eggPool);
    for (let i = 0; i < curCandidates.length; i++) {
        if (!eggSet.has(curCandidates[i]!)) return true;
    }
    return false;
}

/** Shuffle pickPool and return up to eggCandidateCount names. */
export function pickRadarCandidatesFromPool(pickPool: string[], eggCandidateCount: number): string[] {
    const cap = getRadarCandidateCap(pickPool, eggCandidateCount);
    if (cap <= 0 || pickPool.length === 0) return [];
    const pool = pickPool.slice();
    for (let i = pool.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        const tmp = pool[i];
        const swap = pool[j];
        if (tmp == null || swap == null) continue;
        pool[i] = swap;
        pool[j] = tmp;
    }
    return pool.slice(0, cap);
}
