import { EVOLUTION_CONDITION_ITEM_MAP, EVOLUTION_SPECIAL_ITEM_IDS } from '../../constants/evolutions.ts';
import { hasHeldItem } from '../ui/uiItems.ts';
import { isBagCtrlAllItem } from './bagCtrlAllItems.ts';
import { isMobileViewport } from '../ui/breakpoints.ts';

const EVOLUTION_STONE_KEYS_SET = new Set(Object.values(EVOLUTION_CONDITION_ITEM_MAP));
const EVOLUTION_SPECIAL_KEYS_SET = new Set(EVOLUTION_SPECIAL_ITEM_IDS);

/** Utility consumables that must stay in the sac « Divers » tab even if combat rules broaden. */
const BAG_MISC_ITEM_KEYS = new Set([
    'concentrated_milk',
    'roamer_incense_30m',
    'growth_mulch',
    'damp_mulch',
]);

export const BAG_MOBILE_DEFAULT_USE_QTY = 10;

export interface BagItemFilterFlags {
    isKeyItem: boolean;
    isHeldItem: boolean;
    isPermanent: boolean;
    isCombat: boolean;
    isCT: boolean;
    isEvolutionStone: boolean;
    isBerry: boolean;
    isMisc: boolean;
}

export function getBagItemFilterFlags(
    itemKey: string,
    item: { type?: string; effect?: Record<string, unknown> | null; evolutionItem?: boolean } | null | undefined,
): BagItemFilterFlags {
    const safeItem = item || {};
    const isKeyItem = safeItem.type === 'key_item';
    const isHeldItemFlag = hasHeldItem(itemKey);
    const effect = safeItem.effect || null;
    const isVitaminEfficiency = effect?.type === 'vitaminEfficiency';
    const isPermanent = !!(effect && (effect.duration === null || isVitaminEfficiency));
    const isPassiveGainTurbo = !!(effect && effect.type === 'timedGlobalBoost'
        && String(effect.boostType || '').startsWith('passiveGain_'));
    const isCombat = BAG_MISC_ITEM_KEYS.has(itemKey)
        ? false
        : !!(isPassiveGainTurbo || (
            effect
            && effect.duration !== null
            && typeof effect.stat === 'string'
            && effect.stat.length > 0
        ));
    const isCT = typeof itemKey === 'string' && itemKey.startsWith('ct_');
    const isEvolutionStone = EVOLUTION_STONE_KEYS_SET.has(itemKey)
        || EVOLUTION_SPECIAL_KEYS_SET.has(itemKey)
        || safeItem.evolutionItem === true;
    const isBerry = safeItem.type === 'berry';
    const isMisc = !isKeyItem && !isHeldItemFlag && !isPermanent && !isCombat && !isCT && !isEvolutionStone && !isBerry;

    return {
        isKeyItem,
        isHeldItem: isHeldItemFlag,
        isPermanent,
        isCombat,
        isCT,
        isEvolutionStone,
        isBerry,
        isMisc,
    };
}

/** Backpack inventory tab keys (excludes `all`). Display order matches BagItemsGrid. */
export type BagInventoryCategory =
    | 'combat'
    | 'permanent'
    | 'held'
    | 'key'
    | 'evolution_stones'
    | 'berries'
    | 'ct'
    | 'misc';

export const BAG_INVENTORY_CATEGORY_ORDER: readonly BagInventoryCategory[] = [
    'combat',
    'permanent',
    'held',
    'key',
    'evolution_stones',
    'berries',
    'ct',
    'misc',
] as const;

export const BAG_INVENTORY_CATEGORY_I18N_KEYS: Record<BagInventoryCategory, string> = {
    combat: 'bag.filterCombat',
    permanent: 'bag.filterPermanent',
    held: 'bag.filterHeld',
    key: 'bag.filterKey',
    evolution_stones: 'bag.filterEvolutionStones',
    berries: 'bag.filterBerries',
    ct: 'bag.filterCt',
    misc: 'bag.filterMisc',
};

type BagItemDefLike = {
    type?: string;
    effect?: Record<string, unknown> | null;
    evolutionItem?: boolean;
};

/** Single backpack category per item — same rules as buildBagItemsSnapshot filter tabs. */
export function resolveBagItemInventoryCategory(
    itemKey: string,
    item: BagItemDefLike | null | undefined,
): BagInventoryCategory {
    const flags = getBagItemFilterFlags(itemKey, item);
    if (flags.isKeyItem) return 'key';
    if (flags.isHeldItem) return 'held';
    if (flags.isPermanent) return 'permanent';
    if (flags.isCombat) return 'combat';
    if (flags.isEvolutionStone) return 'evolution_stones';
    if (flags.isBerry) return 'berries';
    if (flags.isCT) return 'ct';
    return 'misc';
}

/** Combat tab, Permanent tab, and cosmic pokedollar treasures — mobile default use qty ×10. */
export function isBagMobileBulk10Item(
    itemKey: string,
    item: { type?: string; effect?: Record<string, unknown> | null; evolutionItem?: boolean } | null | undefined,
): boolean {
    if (itemKey === 'star_piece' || itemKey === 'comet_shard') return true;
    const { isCombat, isPermanent, isKeyItem, isHeldItem } = getBagItemFilterFlags(itemKey, item);
    return (isCombat || isPermanent) && !isKeyItem && !isHeldItem;
}

export function resolveBagItemUseQuantity(
    itemKey: string,
    item: { effect?: Record<string, unknown> } | null | undefined,
    requestedQty: number,
    stock: number,
    event: MouseEvent | null | undefined,
    options?: { isMobile?: boolean },
): number {
    let qty = Math.max(1, Math.floor(Number(requestedQty) || 1));
    const isCtrlAll = isBagCtrlAllItem(itemKey, item);

    const mobile = options?.isMobile ?? isMobileViewport();
    if (mobile && qty === 1 && !(event && (event.ctrlKey || event.metaKey)) && isBagMobileBulk10Item(itemKey, item)) {
        qty = BAG_MOBILE_DEFAULT_USE_QTY;
    }

    if (event && (event.ctrlKey || event.metaKey) && isCtrlAll) {
        return Math.max(0, Math.floor(Number(stock) || 0));
    }

    const safeStock = Math.max(0, Math.floor(Number(stock) || 0));
    if (safeStock > 0) {
        return Math.min(qty, safeStock);
    }
    return qty;
}
