/**
 * @file src/lib/miltankFarmRequestPool.ts
 * Builds Miltank farm feed request pool from manual entries + bag tab items.
 */

import { ALL_ITEMS } from '../../constants/balance/shopAndAggregation.ts';
import { RARITY } from '../../constants/core.ts';
import type {
    MiltankFarmRequestCategory,
    MiltankFarmRequestDef,
} from '../../constants/balance/miltankFarm.ts';
import { resolveBagItemInventoryCategory } from './bagItemFilters.ts';

type BagItemLike = {
    rarity?: string;
    type?: string;
    effect?: Record<string, unknown> | null;
    evolutionItem?: boolean;
};

const BALL_KEYS = new Set(['pokeball', 'greatball', 'hyperball', 'masterball']);

const RARITY_FEED_MAP: Record<
    string,
    { category: MiltankFarmRequestCategory; qty: number; weight: number }
> = {
    [RARITY.COMMON]: { category: 'common', qty: 3, weight: 16 },
    [RARITY.RARE]: { category: 'medium', qty: 2, weight: 10 },
    [RARITY.EPIC]: { category: 'rare', qty: 1, weight: 5 },
    [RARITY.LEGENDARY]: { category: 'premium', qty: 1, weight: 2 },
};

const DEFAULT_FEED = RARITY_FEED_MAP[RARITY.COMMON]!;

function mapItemToFeedDef(
    itemKey: string,
    item: { rarity?: string },
): MiltankFarmRequestDef {
    const mapped = RARITY_FEED_MAP[item.rarity ?? ''] ?? DEFAULT_FEED;
    let qty = mapped.qty;
    if (BALL_KEYS.has(itemKey) && (item.rarity ?? RARITY.COMMON) === RARITY.COMMON) {
        qty = 5;
    }

    return {
        itemKey,
        qty,
        weight: mapped.weight,
        category: mapped.category,
    };
}

export function buildBagDerivedMiltankFarmRequests(
    manualKeys: ReadonlySet<string>,
): MiltankFarmRequestDef[] {
    const derived: MiltankFarmRequestDef[] = [];

    for (const [itemKey, rawItem] of Object.entries(ALL_ITEMS)) {
        if (manualKeys.has(itemKey)) continue;

        const item = rawItem as BagItemLike;
        const category = resolveBagItemInventoryCategory(itemKey, item);
        if (category !== 'evolution_stones' && category !== 'misc' && category !== 'berries') continue;

        derived.push(mapItemToFeedDef(itemKey, item));
    }

    derived.sort((a, b) => a.itemKey.localeCompare(b.itemKey));
    return derived;
}

export function buildMiltankFarmRequestPool(
    manual: readonly MiltankFarmRequestDef[],
): MiltankFarmRequestDef[] {
    const manualKeys = new Set(manual.map((e) => e.itemKey));
    return [...manual, ...buildBagDerivedMiltankFarmRequests(manualKeys)];
}
