/** Daily escalating cost for Miltank farm request rerolls (farm-wide counter). */

import { MILTANK_FARM } from '../../constants/balance/miltankFarm.ts';
import type { MiltankFarmState } from './miltankFarmLogic.ts';
import { getLocalCalendarDayKey } from './pokedexRadarRefresh.ts';

export function getMiltankRequestRerollCost(refreshesUsedToday: number): number {
    const used = Math.max(0, Math.floor(Number(refreshesUsedToday) || 0));
    return MILTANK_FARM.rerollCostPokedollars * Math.pow(2, used);
}

export function resetMiltankRequestRerollDailyIfNeeded(
    state: MiltankFarmState,
    dayKey: string = getLocalCalendarDayKey(),
): void {
    if (!state || typeof state !== 'object') return;
    const savedDay = typeof state.requestRerollDayKey === 'string' ? state.requestRerollDayKey : '';
    if (savedDay !== dayKey) {
        state.requestRerollDayKey = dayKey;
        state.requestRerollCountToday = 0;
    }
    if (typeof state.requestRerollCountToday !== 'number' || !Number.isFinite(state.requestRerollCountToday)) {
        state.requestRerollCountToday = 0;
    } else {
        state.requestRerollCountToday = Math.max(0, Math.floor(state.requestRerollCountToday));
    }
    if (typeof state.requestRerollDayKey !== 'string' || !state.requestRerollDayKey) {
        state.requestRerollDayKey = dayKey;
    }
}

export function getNextMiltankRequestRerollCost(state: MiltankFarmState, now = new Date()): number {
    resetMiltankRequestRerollDailyIfNeeded(state, getLocalCalendarDayKey(now));
    return getMiltankRequestRerollCost(state.requestRerollCountToday ?? 0);
}
