import { coerceStr } from './coerceStr.ts';

/** Items that support Ctrl/Cmd+click to use the full stack from the bag. */
export function isBagCtrlAllItem(
    itemKey: string,
    item: { effect?: Record<string, unknown> } | null | undefined,
): boolean {
    const effect = item?.effect;
    if (!effect) return false;

    if (effect.duration === null) return true;

    const effectType = coerceStr(effect.type, '');
    if (effectType === 'vitaminEfficiency') return true;
    if (effectType === 'timeDust' || effectType === 'pokedollars') return true;

    if (itemKey === 'hatch_charm_1h' || itemKey === 'shiny_charm_30m') return true;

    if (effectType === 'timedGlobalBoost' && coerceStr(effect.boostType, '').startsWith('passiveGain_')) {
        return true;
    }

    const stat = effect.stat;
    const duration = effect.duration;
    if (
        stat != null &&
        stat !== '' &&
        typeof duration === 'number' &&
        duration > 0 &&
        !effectType
    ) {
        return true;
    }

    return false;
}
