const BERRY_DEX_KEY_SET = new Set<string>(BERRY_DEX_KEYS);

export function isMiltankFeedBerryItemKey(itemKey: string): boolean {
    return BERRY_DEX_KEY_SET.has(itemKey);
}

export function getUnlockedBerryKeysForMiltankRequests(state: MiltankFarmState): ReadonlySet<string> {
    const unlocked = state.berryTree?.unlockedBerryKeys ?? [];
    return new Set(unlocked.filter((key) => isMiltankFeedBerryItemKey(key)));
}

function filterMiltankRequestPool(
    pool: readonly MiltankFarmRequestDef[],
    farmLevel: number,
    unlockedBerries: ReadonlySet<string>,
): MiltankFarmRequestDef[] {
    return pool.filter((entry) => {
        if (farmLevel < getRequestMinFarmLevel(entry.category)) return false;
        if (isMiltankFeedBerryItemKey(entry.itemKey) && !unlockedBerries.has(entry.itemKey)) return false;
        return true;
    });
}

