function defaultPastureEntryProgress(): Pick<
    MiltankPastureEntry,
    | 'xp'
    | 'level'
    | 'satiety'
    | 'currentRequest'
    | 'productionBoostUntil'
    | 'productionBoostMult'
    | 'lastRerollAt'
    | 'talentRanks'
> {
    return {
        xp: 0,
        level: 0,
        satiety: 0,
        currentRequest: null,
        productionBoostUntil: 0,
        productionBoostMult: MILTANK_FARM.feedBoostMult,
        lastRerollAt: 0,
        talentRanks: {},
    };
}

export function syncPastureEntryProgression(entry: MiltankPastureEntry): void {
    entry.xp = Math.max(0, Math.floor(Number(entry.xp) || 0));
    entry.level = getMiltankFarmLevel(entry.xp);
}

export function syncFarmAggregateLevel(state: MiltankFarmState): void {
    const entries = state.pastureEntries ?? [];
    let sumLevel = 0;
    let sumXp = 0;
    for (const entry of entries) {
        syncPastureEntryProgression(entry);
        sumLevel += Math.max(0, entry.level);
        sumXp += entry.xp;
    }
    state.level = sumLevel;
    state.bondLevel = sumLevel;
    state.xp = sumXp;
}

/** Highest individual Miltank level among all pasture entries (narrative + assigned). */
export function getMaxPastureMiltankLevel(state: MiltankFarmState): number {
    normalizeMiltankFarmState(state);
    let maxLevel = 0;
    for (const entry of state.pastureEntries ?? []) {
        syncPastureEntryProgression(entry);
        maxLevel = Math.max(maxLevel, Math.max(0, entry.level));
    }
    return maxLevel;
}

/** Sum of all pasture entry levels — matches the farm HUD "Niveau ferme". */
export function getMiltankFarmLevelSum(state: MiltankFarmState): number {
    normalizeMiltankFarmState(state);
    let sumLevel = 0;
    for (const entry of state.pastureEntries ?? []) {
        syncPastureEntryProgression(entry);
        sumLevel += Math.max(0, entry.level);
    }
    state.level = sumLevel;
    state.bondLevel = sumLevel;
    return sumLevel;
}

export function getMiltankFarmStoredMilkTotal(state: MiltankFarmState): number {
    normalizeMiltankFarmState(state);
    return (state.pastureEntries ?? []).reduce(
        (sum, entry) => sum + Math.max(0, Math.floor(Number(entry.storedMilk) || 0)),
        0,
    );
}

/** Bag moomoo_milk plus unclaimed stored milk on pasture entries. */
export function getAvailableMoomooMilk(
    bagQty: number,
    farmState: MiltankFarmState | null | undefined,
): number {
    const bag = Math.max(0, Math.floor(Number(bagQty) || 0));
    if (!farmState) return bag;
    return bag + getMiltankFarmStoredMilkTotal(farmState);
}

/** Consumes bag milk first, then unclaimed stored pasture milk. */
export function consumeMoomooMilk(
    bagItems: Record<string, number>,
    farmState: MiltankFarmState | null | undefined,
    amount: number,
): boolean {
    const need = Math.max(0, Math.floor(Number(amount) || 0));
    if (need <= 0) return true;

    let remaining = need;
    const bag = Math.max(0, Math.floor(Number(bagItems.moomoo_milk) || 0));
    const fromBag = Math.min(bag, remaining);
    if (fromBag > 0) {
        remaining -= fromBag;
        const left = bag - fromBag;
        if (left > 0) bagItems.moomoo_milk = left;
        else delete bagItems.moomoo_milk;
    }

    if (remaining > 0 && farmState) {
        normalizeMiltankFarmState(farmState);
        for (const entry of farmState.pastureEntries ?? []) {
            if (remaining <= 0) break;
            const stored = Math.max(0, Math.floor(Number(entry.storedMilk) || 0));
            if (stored <= 0) continue;
            const take = Math.min(stored, remaining);
            entry.storedMilk = stored - take;
            remaining -= take;
        }
        syncLegacyMilkTotals(farmState);
    }

    return remaining === 0;
}

function migratePastureTalentToCare(ranks: Record<string, number>): void {
    const pastureRank = Math.floor(Number(ranks.pasture) || 0);
    if (pastureRank <= 0) return;
    if (!ranks.care || Math.floor(Number(ranks.care) || 0) < pastureRank) {
        ranks.care = pastureRank;
    }
    delete ranks.pasture;
}

function pastureEntryNeedsMigration(entry: MiltankPastureEntry): boolean {
    return entry.xp == null || Number.isNaN(Number(entry.xp));
}

function migrateNarrativeEntryFromGlobals(entry: MiltankPastureEntry, state: MiltankFarmState): void {
    const defaults = defaultPastureEntryProgress();
    entry.xp = Math.max(0, Math.floor(Number(state.xp) || Number(state.totalFeeds) || 0));
    entry.satiety = Math.max(
        0,
        Math.min(MILTANK_FARM.satietyMax, Math.floor(Number(state.satiety) || 0)),
    );
    entry.currentRequest = state.currentRequest ?? null;
    entry.productionBoostUntil = Math.max(0, Number(state.productionBoostUntil) || 0);
    entry.productionBoostMult = Number(state.productionBoostMult) || defaults.productionBoostMult;
    entry.lastRerollAt = Math.max(0, Number(state.lastRerollAt) || 0);
    syncPastureEntryProgression(entry);
}

function narrativeNeedsLegacyMigration(entry: MiltankPastureEntry, state: MiltankFarmState): boolean {
    if (pastureEntryNeedsMigration(entry)) return true;
    const legacyXp = Math.max(0, Number(state.xp) || Number(state.totalFeeds) || 0);
    if (legacyXp <= 0) return false;
    return entry.xp === 0 && entry.level === 0;
}

function ensurePastureEntryFields(entry: MiltankPastureEntry, state: MiltankFarmState): void {
    if (entry.isNarrative || entry.uid === NARRATIVE_MILTANK_UID) {
        if (narrativeNeedsLegacyMigration(entry, state)) {
            migrateNarrativeEntryFromGlobals(entry, state);
            return;
        }
    } else if (pastureEntryNeedsMigration(entry)) {
        Object.assign(entry, defaultPastureEntryProgress());
        return;
    }
    const satietyMax = getEntrySatietyMax(entry);
    entry.satiety = Math.max(0, Math.min(satietyMax, Number(entry.satiety) || 0));
    if (!entry.productionBoostMult) entry.productionBoostMult = MILTANK_FARM.feedBoostMult;
    if (entry.currentRequest === undefined) entry.currentRequest = null;
    entry.productionBoostUntil = Math.max(0, Number(entry.productionBoostUntil) || 0);
    entry.lastRerollAt = Math.max(0, Number(entry.lastRerollAt) || 0);
    if (!entry.talentRanks || typeof entry.talentRanks !== 'object') {
        entry.talentRanks = {};
    }
    migratePastureTalentToCare(entry.talentRanks);
    syncPastureEntryProgression(entry);
}

function migrateGlobalTalentRanksToEntries(state: MiltankFarmState): void {
    const global = state.talentRanks ?? {};
    const hasGlobal = Object.values(global).some((v) => Math.floor(Number(v) || 0) > 0);
    if (!hasGlobal) return;

    const narrative = getNarrativePastureEntry(state);
    if (!narrative.talentRanks || typeof narrative.talentRanks !== 'object') {
        narrative.talentRanks = {};
    }
    const narrativeSpent = Object.values(narrative.talentRanks)
        .reduce((sum, v) => sum + Math.max(0, Math.floor(Number(v) || 0)), 0);
    if (narrativeSpent === 0) {
        narrative.talentRanks = { ...global };
    }
    state.talentRanks = {};
}

export function createNarrativePastureEntry(
    storedMilk = 0,
    pendingMilk = 0,
): MiltankPastureEntry {
    return {
        uid: NARRATIVE_MILTANK_UID,
        storedMilk,
        pendingMilk,
        isNarrative: true,
        ...defaultPastureEntryProgress(),
    };
}

export function createAssignedPastureEntry(uid: string): MiltankPastureEntry {
    return {
        uid,
        storedMilk: 0,
        pendingMilk: 0,
        ...defaultPastureEntryProgress(),
    };
}

export function getNarrativePastureEntry(state: MiltankFarmState): MiltankPastureEntry {
    const entries = state.pastureEntries ?? [];
    const found = entries.find((e) => e.uid === NARRATIVE_MILTANK_UID || e.isNarrative);
    if (found) return found;
    const narrative = createNarrativePastureEntry();
    state.pastureEntries = [narrative, ...entries];
    return narrative;
}

export function getMiltankFarmSpeciesKey(creature: CreatureData | null | undefined): string {
    if (!creature) return '';
    const legacy = creature.species;
    if (typeof legacy === 'string' && legacy.length > 0) return legacy;
    return String(creature.name || '');
}

export function isPastureMiltank(creature: CreatureData | null | undefined): boolean {
    return getMiltankFarmSpeciesKey(creature) === 'Miltank';
}

/** All player-owned Miltank (team, storage, pension, pasture, ultimate slot). */
export function collectPlayerOwnedPastureMiltanks(game: {
    playerTeam?: CreatureData[] | null;
    storage?: CreatureData[] | null;
    pension?: CreatureData[] | null;
    miltankFarmState?: MiltankFarmState | null;
    ultimateSlot?: CreatureData | null;
}): CreatureData[] {
    const out: CreatureData[] = [];
    const seenUids = new Set<string>();
    const add = (creature: CreatureData | null | undefined): void => {
        if (!creature || !isPastureMiltank(creature)) return;
        const uid = String(creature.uid || '');
        if (uid) {
            if (seenUids.has(uid)) return;
            seenUids.add(uid);
        }
        out.push(creature);
    };
    for (const arr of [game.playerTeam, game.storage, game.pension]) {
        if (!Array.isArray(arr)) continue;
        for (const creature of arr) add(creature);
    }
    const pasture = game.miltankFarmState?.pastureCreatures;
    if (Array.isArray(pasture)) {
        for (const creature of pasture) add(creature);
    }
    add(game.ultimateSlot ?? undefined);
    return out;
}

export function matchesCreatureNameVariant(
    creature: CreatureData,
    nameToFind: string,
    isShiny: boolean,
    isShadow: boolean,
): boolean {
    return (
        creature.name === nameToFind
        && !!creature.isShiny === !!isShiny
        && !!creature.isShadow === !!isShadow
    );
}

export function getPastureNormalCreature(state: MiltankFarmState): CreatureData | null {
    return (state.pastureCreatures ?? []).find((c) => c && !c.isShiny) ?? null;
}

export function getPastureShinyCreature(state: MiltankFarmState): CreatureData | null {
    return (state.pastureCreatures ?? []).find((c) => c && !!c.isShiny) ?? null;
}

export function enforcePastureCreatureOrder(state: MiltankFarmState): void {
    const creatures = (state.pastureCreatures ?? []).filter(
        (c) => c && c.uid && isPastureMiltank(c),
    );
    const normal = creatures.find((c) => !c.isShiny) ?? null;
    const shiny = creatures.find((c) => !!c.isShiny) ?? null;
    const ordered: CreatureData[] = [];
    if (normal) ordered.push(normal);
    if (shiny) ordered.push(shiny);
    state.pastureCreatures = ordered;
}

/** Evict invalid pasture occupants; mutates state.pastureCreatures. Returns creatures to return to storage. */
export function evictInvalidPastureCreatures(state: MiltankFarmState): CreatureData[] {
    const creatures = (state.pastureCreatures ?? []).filter((c) => c && c.uid);
    const evicted: CreatureData[] = [];
    const invalid = creatures.filter((c) => !isPastureMiltank(c));
    evicted.push(...invalid);

    const normals = creatures.filter((c) => isPastureMiltank(c) && !c.isShiny);
    const shinies = creatures.filter((c) => isPastureMiltank(c) && !!c.isShiny);
    if (normals.length > 1) evicted.push(...normals.slice(1));

    const keepNormal = normals[0] ?? null;
    let keepShiny = shinies[0] ?? null;
    if (shinies.length > 1) evicted.push(...shinies.slice(1));

    if (keepShiny && !keepNormal) {
        evicted.push(keepShiny);
        keepShiny = null;
    }

    const maxSlots = resolveMaxAssignableSlots(state);
    if (maxSlots < 2 && keepNormal && keepShiny) {
        evicted.push(keepShiny);
        keepShiny = null;
    }

    const valid: CreatureData[] = [];
    if (keepNormal) valid.push(keepNormal);
    if (keepShiny) valid.push(keepShiny);
    state.pastureCreatures = valid;
    enforcePastureCreatureOrder(state);
    return evicted;
}

/** Remove pasture copies whose uid also exists on team/storage/pension/ultimate (data corruption). */
export function dedupePastureRosterReferences(game: {
    playerTeam?: CreatureData[] | null;
    storage?: CreatureData[] | null;
    pension?: CreatureData[] | null;
    ultimateSlot?: CreatureData | null;
    miltankFarmState?: MiltankFarmState | null;
}): void {
    const state = game.miltankFarmState;
    if (!state?.pastureCreatures?.length) return;

    const rosterUids = new Set<string>();
    for (const arr of [game.playerTeam, game.storage, game.pension]) {
        if (!Array.isArray(arr)) continue;
        for (const creature of arr) {
            const uid = String(creature?.uid || '');
            if (uid && isPastureMiltank(creature)) rosterUids.add(uid);
        }
    }
    const ultimateUid = String(game.ultimateSlot?.uid || '');
    if (ultimateUid && isPastureMiltank(game.ultimateSlot)) {
        rosterUids.add(ultimateUid);
    }

    const before = state.pastureCreatures.length;
    state.pastureCreatures = state.pastureCreatures.filter((creature) => {
        if (!creature?.uid || !isPastureMiltank(creature)) return true;
        return !rosterUids.has(String(creature.uid));
    });
    if (state.pastureCreatures.length !== before) {
        enforcePastureCreatureOrder(state);
    }
}

export function canAssignCreatureToPastureSlot(
    creature: CreatureData,
    slot: PasturePlayerSlot,
): boolean {
    if (!isPastureMiltank(creature)) return false;
    return slot === 'normal' ? !creature.isShiny : !!creature.isShiny;
}

export function getNextPasturePlayerSlot(state: MiltankFarmState): PasturePlayerSlot | null {
    syncMiltankFarmProgression(state);
    const maxSlots = resolveMaxAssignableSlots(state);
    state.maxAssignableSlots = maxSlots;
    enforcePastureCreatureOrder(state);
    const assigned = state.pastureCreatures ?? [];
    if (!getPastureNormalCreature(state) && assigned.length < maxSlots) return 'normal';
    if (
        getPastureNormalCreature(state)
        && !getPastureShinyCreature(state)
        && maxSlots >= 2
        && assigned.length < maxSlots
    ) {
        return 'shiny';
    }
    return null;
}

export function validatePastureAssign(
    state: MiltankFarmState,
    creature: CreatureData,
):
    | { ok: true; slot: PasturePlayerSlot }
    | { ok: false; reason: PastureAssignRejectReason } {
    if (!isPastureMiltank(creature)) return { ok: false, reason: 'not_miltank' };

    const uid = String(creature.uid || '');
    if ((state.pastureCreatures ?? []).some((c) => c && String(c.uid) === uid)) {
        return { ok: false, reason: 'already_assigned' };
    }

    const slot = getNextPasturePlayerSlot(state);
    if (!slot) return { ok: false, reason: 'pasture_full' };

    if (slot === 'shiny' && !getPastureNormalCreature(state)) {
        return { ok: false, reason: 'need_normal_first' };
    }

    if (!canAssignCreatureToPastureSlot(creature, slot)) {
        return { ok: false, reason: 'wrong_slot' };
    }

    return { ok: true, slot };
}

function syncPastureEntriesOrder(state: MiltankFarmState): void {
    enforcePastureCreatureOrder(state);
    const narrative = getNarrativePastureEntry(state);
    const entriesByUid = new Map(
        (state.pastureEntries ?? []).map((e) => [e.uid, e] as const),
    );
    const ordered: MiltankPastureEntry[] = [narrative];
    for (const creature of state.pastureCreatures ?? []) {
        if (!creature?.uid) continue;
        const uid = String(creature.uid);
        const entry = entriesByUid.get(uid);
        ordered.push(entry ?? createAssignedPastureEntry(uid));
    }
    state.pastureEntries = ordered;
}

/** Migrate legacy global milk + sync pasture entry list with assigned creatures. */
export function normalizeMiltankFarmState(state: MiltankFarmState): void {
    if (!Array.isArray(state.pastureCreatures)) state.pastureCreatures = [];
    if (!state.talentRanks || typeof state.talentRanks !== 'object') state.talentRanks = {};
    migratePastureTalentToCare(state.talentRanks);
    if (state.xp == null || Number.isNaN(Number(state.xp))) {
        state.xp = Math.max(0, Number(state.totalFeeds) || 0);
    }
    if (state.level == null || Number.isNaN(Number(state.level))) {
        state.level = Math.max(0, Number(state.bondLevel) || 0);
    }
    if (!state.productionBoostMult) state.productionBoostMult = MILTANK_FARM.feedBoostMult;
    const satietyMax = MILTANK_FARM.satietyMax;
    if (state.satiety == null || Number.isNaN(Number(state.satiety))) {
        state.satiety = 0;
    }
    state.satiety = Math.max(0, Math.min(satietyMax, Math.floor(Number(state.satiety) || 0)));

    if (!Array.isArray(state.pastureEntries)) {
        state.pastureEntries = [
            createNarrativePastureEntry(
                Math.max(0, Math.floor(Number(state.storedMilk) || 0)),
                Math.max(0, Number(state.pendingMilk) || 0),
            ),
        ];
    }

    const narrative = getNarrativePastureEntry(state);
    const hadOnlyLegacy = state.pastureEntries!.length === 1
        && state.pastureEntries![0] === narrative
        && (Number(state.storedMilk) || Number(state.pendingMilk));
    if (hadOnlyLegacy && narrative.storedMilk === 0 && narrative.pendingMilk === 0) {
        narrative.storedMilk = Math.max(0, Math.floor(Number(state.storedMilk) || 0));
        narrative.pendingMilk = Math.max(0, Number(state.pendingMilk) || 0);
    }

    const creatureUids = new Set(
        state.pastureCreatures
            .filter((c) => c && c.uid)
            .map((c) => String(c.uid)),
    );

    state.pastureEntries = state.pastureEntries!.filter(
        (e) => e.isNarrative || e.uid === NARRATIVE_MILTANK_UID || creatureUids.has(e.uid),
    );

    for (const creature of state.pastureCreatures) {
        if (!creature?.uid) continue;
        const uid = String(creature.uid);
        if (!state.pastureEntries!.some((e) => e.uid === uid)) {
            state.pastureEntries!.push(createAssignedPastureEntry(uid));
        }
    }

    if (!state.pastureEntries!.some((e) => e.isNarrative || e.uid === NARRATIVE_MILTANK_UID)) {
        state.pastureEntries!.unshift(createNarrativePastureEntry());
    }

    for (const entry of state.pastureEntries!) {
        ensurePastureEntryFields(entry, state);
    }

    migrateGlobalTalentRanksToEntries(state);

    if (!state.selectedPastureUid) {
        state.selectedPastureUid = NARRATIVE_MILTANK_UID;
    }
    if (!state.pastureEntries!.some((e) => e.uid === state.selectedPastureUid)) {
        state.selectedPastureUid = NARRATIVE_MILTANK_UID;
    }

    enforcePastureCreatureOrder(state);
    syncPastureEntriesOrder(state);
    syncMiltankFarmProgression(state);
    state.maxAssignableSlots = resolveMaxAssignableSlots(state);
    if (!Array.isArray(state.guardianAssignments)) state.guardianAssignments = [];
    if (!Array.isArray(state.activeDebuffs)) state.activeDebuffs = [];
    if (!Array.isArray(state.pendingIncidentPulses)) state.pendingIncidentPulses = [];
    if (state.pendingIncidentAlert == null) state.pendingIncidentAlert = null;
    if (!Array.isArray(state.activeThreatApproaches)) state.activeThreatApproaches = [];
    if (!Array.isArray(state.pendingThreatAttacks)) state.pendingThreatAttacks = [];
    for (const attack of state.pendingThreatAttacks) {
        if (attack.arrivedAtPasture !== true && attack.arrivedAtPasture !== false) {
            attack.arrivedAtPasture = attack.approachProgressAtStart >= MILTANK_FARM_THREATS.threatApproachArrivedRatio;
        }
    }
    for (const approach of state.activeThreatApproaches) {
        if (approach.approachSide !== 'left' && approach.approachSide !== 'right') {
            approach.approachSide = 'left';
        }
    }
    if (!Number.isFinite(Number(state.incidentCheckAccumulatorMs))) state.incidentCheckAccumulatorMs = 0;
    if (state.threatCombatWins == null || Number.isNaN(Number(state.threatCombatWins))) {
        state.threatCombatWins = 0;
    }
    state.threatCombatWins = Math.max(
        0,
        Math.min(
            MILTANK_FARM_THREATS.threatCombatMaxWins,
            Math.floor(Number(state.threatCombatWins) || 0),
        ),
    );
    syncLegacyMilkTotals(state);
    resetMiltankRequestRerollDailyIfNeeded(state);
    state.berryTree = normalizeBerryTreeState(state.berryTree);

    const now = Date.now();
    const unlockedBerries = getUnlockedBerryKeysForMiltankRequests(state);
    for (const entry of state.pastureEntries!) {
        const entryLevel = Math.max(0, Math.floor(Number(entry.level) || Number(state.level) || 0));
        const req = entry.currentRequest;
        if (!req) continue;
        const invalidBerry = isMiltankFeedBerryItemKey(req.itemKey) && !unlockedBerries.has(req.itemKey);
        if (req.itemKey === 'evolution_stone' || invalidBerry) {
            entry.currentRequest = rollMiltankFarmRequest(now, entryLevel, Math.random, unlockedBerries);
        }
    }
}

export function syncLegacyMilkTotals(state: MiltankFarmState): void {
    const entries = state.pastureEntries ?? [];
    state.storedMilk = entries.reduce((sum, e) => sum + Math.floor(Number(e.storedMilk) || 0), 0);
    state.pendingMilk = entries.reduce((sum, e) => sum + (Number(e.pendingMilk) || 0), 0);
}

function pickWeightedRequest(
    farmLevel: number,
    rng: () => number,
    unlockedBerries: ReadonlySet<string> = new Set(),
): MiltankFarmRequestDef {
    let effective = filterMiltankRequestPool(MILTANK_FARM_REQUEST_POOL, farmLevel, unlockedBerries);
    if (effective.length === 0) {
        effective = filterMiltankRequestPool(MILTANK_FARM_REQUEST_POOL, 0, unlockedBerries);
    }
    if (effective.length === 0) {
        effective = MILTANK_FARM_REQUEST_POOL.filter(
            (entry) => !isMiltankFeedBerryItemKey(entry.itemKey),
        );
    }
    let total = 0;
    for (const entry of effective) total += entry.weight;
    let roll = rng() * total;
    for (const entry of effective) {
        roll -= entry.weight;
        if (roll <= 0) return entry;
    }
    return effective[effective.length - 1];
}

export function rollMiltankFarmRequest(
    now: number,
    farmLevel = 0,
    rng: () => number = Math.random,
    unlockedBerries: ReadonlySet<string> = new Set(),
): MiltankFarmRequest {
    const def = pickWeightedRequest(farmLevel, rng, unlockedBerries);
    return {
        itemKey: def.itemKey,
        qty: def.qty,
        expiresAt: now + MILTANK_FARM.requestRotationMs,
        category: def.category,
    };
}

export function ensureMiltankFarmRequestForEntry(
    entry: MiltankPastureEntry,
    entryLevel: number,
    now: number,
    rng: () => number = Math.random,
    unlockedBerries: ReadonlySet<string> = new Set(),
): void {
    const req = entry.currentRequest;
    if (req && req.expiresAt > now) return;
    const def = pickWeightedRequest(entryLevel, rng, unlockedBerries);
    const rotationMs = entry.level >= 3
        ? Math.floor(MILTANK_FARM.requestRotationMs * MILTANK_FARM_TALENTS.requestRotationLevel3Mult)
        : MILTANK_FARM.requestRotationMs;
    entry.currentRequest = {
        itemKey: def.itemKey,
        qty: def.qty,
        expiresAt: now + rotationMs,
        category: def.category,
    };
}

export function ensureMiltankFarmRequests(
    state: MiltankFarmState,
    now: number,
    rng: () => number = Math.random,
): void {
    if (!state.unlocked) return;
    syncMiltankFarmProgression(state);
    const unlockedBerries = getUnlockedBerryKeysForMiltankRequests(state);
    for (const entry of state.pastureEntries ?? []) {
        ensureMiltankFarmRequestForEntry(entry, entry.level, now, rng, unlockedBerries);
    }
}

export function ensureMiltankFarmRequest(
    state: MiltankFarmState,
    now: number,
    rng: () => number = Math.random,
): void {
    ensureMiltankFarmRequests(state, now, rng);
}

export function getMiltankFarmRequestDef(itemKey: string): MiltankFarmRequestDef | null {
    return MILTANK_FARM_REQUEST_POOL.find((d) => d.itemKey === itemKey) ?? null;
}

export function getSatietyMax(): number {
    return MILTANK_FARM.satietyMax;
}

export function getSatietyFeedRoom(
    satiety: number,
    category: string,
    satietyMax = MILTANK_FARM.satietyMax,
): number {
    const floor = Math.floor(Number(satiety) || 0);
    return satietyMax - floor - getFeedSatietyGain(category);
}

export function canFeedEntryBySatiety(entry: MiltankPastureEntry): boolean {
    const satietyMax = getEntrySatietyMax(entry);
    const category = entry.currentRequest?.category;
    if (!category) {
        return Math.floor(Number(entry.satiety) || 0) < satietyMax;
    }
    return getSatietyFeedRoom(entry.satiety, category, satietyMax) >= 0;
}

export function canFeedBySatiety(state: MiltankFarmState, pastureUid?: string): boolean {
    normalizeMiltankFarmState(state);
    const entry = getPastureEntryByUid(state, pastureUid ?? state.selectedPastureUid);
    if (!entry) return false;
    return canFeedEntryBySatiety(entry);
}

export function getFeedSatietyGain(category: string): number {
    return getFeedSatietyForCategory(category);
}

export function applySatietyDecayToEntry(entry: MiltankPastureEntry, elapsedMs: number): void {
    if (elapsedMs <= 0) return;
    const hours = elapsedMs / (60 * 60 * 1000);
    const decay = hours * MILTANK_FARM.satietyDecayPerHour * getCareSatietyDecayMult(entry);
    entry.satiety = Math.max(0, (Number(entry.satiety) || 0) - decay);
}

export function applySatietyDecay(state: MiltankFarmState, elapsedMs: number): void {
    if (elapsedMs <= 0) return;
    normalizeMiltankFarmState(state);
    for (const entry of state.pastureEntries ?? []) {
        applySatietyDecayToEntry(entry, elapsedMs);
    }
}

export function addSatietyOnFeed(entry: MiltankPastureEntry, category: string): void {
    const gain = getFeedSatietyGain(category);
    const satietyMax = getEntrySatietyMax(entry);
    entry.satiety = Math.min(
        satietyMax,
        (Number(entry.satiety) || 0) + gain,
    );
}

export function getFarmWideProductionMult(state: MiltankFarmState, now: number): number {
    const until = Number(state.farmProductionBoostUntil) || 0;
    if (until <= now) return 1;
    const mult = Number(state.farmProductionBoostMult);
    return Number.isFinite(mult) && mult > 0 ? mult : 1;
}

export function applyFarmWideProductionBoost(
    state: MiltankFarmState,
    mult: number,
    durationMs: number,
    now = Date.now(),
): void {
    const safeMult = Number.isFinite(mult) && mult > 0 ? mult : 1;
    const safeDuration = Math.max(0, Math.floor(Number(durationMs) || 0));
    if (safeDuration <= 0) return;
    const until = Number(state.farmProductionBoostUntil) || 0;
    const wasActive = until > now;
    state.farmProductionBoostMult = safeMult;
    state.farmProductionBoostUntil = (wasActive ? until : now) + safeDuration;
}

function getPastureSlotMult(entry: MiltankPastureEntry, assignedIndex: number): number {
    const slotIdx = entry.isNarrative || entry.uid === NARRATIVE_MILTANK_UID ? 0 : assignedIndex;
    const mults = MILTANK_FARM.assignedMiltankRateMults;
    return mults[Math.min(slotIdx, mults.length - 1)] ?? mults[mults.length - 1] ?? 0.45;
}

export function computePastureMilkPerHour(
    state: MiltankFarmState,
    entry: MiltankPastureEntry,
    assignedIndex: number,
    now: number,
    opts?: { milkSpeedMult?: number },
): number {
    syncMiltankFarmProgression(state);
    syncPastureEntryProgression(entry);
    let rate = MILTANK_FARM.baseMilkPerHour * getPastureSlotMult(entry, assignedIndex);
    rate *= 1 + getLevelProductionMult(entry) + getProductionTalentMult(entry);
    if (entry.productionBoostUntil > now) {
        rate *= Number(entry.productionBoostMult) || MILTANK_FARM.feedBoostMult;
    }
    rate *= getPastureProductionMult(state, entry.uid, now);
    rate *= getFarmWideProductionMult(state, now);
    const milkSpeed = Math.max(0, Number(opts?.milkSpeedMult) || 0);
    if (milkSpeed > 0) rate *= 1 + milkSpeed;
    return rate;
}

/** @deprecated Use {@link computePastureMilkPerHour} */
export function computeNarrativeMilkPerHour(
    state: MiltankFarmState,
    entry: MiltankPastureEntry,
    now: number,
): number {
    return computePastureMilkPerHour(state, entry, 0, now);
}

/** @deprecated Use {@link computePastureMilkPerHour} */
export function computeAssignedMilkPerHour(
    entry: MiltankPastureEntry,
    assignedIndex: number,
    state: MiltankFarmState = { unlocked: false } as MiltankFarmState,
    now: number = 0,
): number {
    return computePastureMilkPerHour(state, entry, assignedIndex, now);
}

export function getPastureEntryStockCap(state: MiltankFarmState, entry: MiltankPastureEntry): number {
    if (entry.isNarrative || entry.uid === NARRATIVE_MILTANK_UID) {
        return getMiltankFarmStockCap(entry.level, state.pastureUpgraded);
    }
    return MILTANK_FARM.perMiltankStockCap;
}

export function computePastureEntryMilkPerHour(
    state: MiltankFarmState,
    entry: MiltankPastureEntry,
    assignedIndex: number,
    now: number,
    opts?: { milkSpeedMult?: number },
): number {
    return computePastureMilkPerHour(state, entry, assignedIndex, now, opts);
}

export function computeMiltankMilkPerHour(
    state: MiltankFarmState,
    _ctx: Record<string, unknown> = {},
    now: number,
): number {
    normalizeMiltankFarmState(state);
    const milkSpeedMult = Math.max(0, Number((_ctx as { milkSpeedMult?: number }).milkSpeedMult) || 0);
    const opts = milkSpeedMult > 0 ? { milkSpeedMult } : undefined;
    let total = 0;
    let assignedIndex = 0;
    for (const entry of state.pastureEntries ?? []) {
        total += computePastureEntryMilkPerHour(state, entry, assignedIndex, now, opts);
        if (!entry.isNarrative && entry.uid !== NARRATIVE_MILTANK_UID) assignedIndex += 1;
    }
    return total;
}

function tickPastureEntryMilk(
    entry: MiltankPastureEntry,
    milkPerHour: number,
    hours: number,
    cap: number,
): void {
    const produced = milkPerHour * hours;
    let pending = (Number(entry.pendingMilk) || 0) + produced;
    let stored = Math.max(0, Math.floor(Number(entry.storedMilk) || 0));
    const room = Math.max(0, cap - stored);
    const whole = Math.min(room, Math.floor(pending));
    pending -= whole;
    stored += whole;
    if (stored >= cap) pending = Math.min(pending, 0.999);
    entry.pendingMilk = pending;
    entry.storedMilk = stored;
}

export interface MiltankFarmTickResult {
    pulses: FarmIncidentPulse[];
    expiredApproaches: FarmThreatApproach[];
    approachesSpawned: number;
    spawnedApproaches: FarmThreatApproach[];
}

export function tickMiltankFarmState(
    state: MiltankFarmState,
    now: number,
    threatCtx?: FarmThreatTickContext,
    masteryOpts?: {
        milkSpeedMult?: number;
        berryProductionTimeReduction?: number;
    },
): MiltankFarmTickResult {
    const empty: MiltankFarmTickResult = {
        pulses: [],
        expiredApproaches: [],
        approachesSpawned: 0,
        spawnedApproaches: [],
    };
    if (!state.unlocked) return empty;
    normalizeMiltankFarmState(state);
    ensureMiltankFarmRequests(state, now);

    const last = Math.max(0, Number(state.lastTickAt) || now);
    let elapsed = Math.max(0, now - last);
    if (elapsed <= 0) {
        state.lastTickAt = now;
        return empty;
    }
    const offlineCap = MILTANK_FARM.offlineCapMs;
    elapsed = Math.min(elapsed, offlineCap);
    applySatietyDecay(state, elapsed);

    let incidentPulses: FarmIncidentPulse[] = [];
    let approachesSpawned = 0;
    let spawnedApproaches: FarmThreatApproach[] = [];
    if (threatCtx) {
        const roll = rollFarmIncidents(state, elapsed, threatCtx, now);
        incidentPulses = roll.pulses;
        approachesSpawned = roll.approachesSpawned;
        spawnedApproaches = roll.spawnedApproaches;
    }

    const expiredRaw = getExpiredThreatApproaches(state, now);
    const expiredApproaches: FarmThreatApproach[] = [];
    for (const approach of expiredRaw) {
        removeThreatApproach(state, approach.id);
        expiredApproaches.push(approach);
    }

    const hours = elapsed / (60 * 60 * 1000);

    let assignedIndex = 0;
    const milkOpts = (masteryOpts?.milkSpeedMult ?? 0) > 0
        ? { milkSpeedMult: masteryOpts!.milkSpeedMult }
        : undefined;
    for (const entry of state.pastureEntries ?? []) {
        const rate = computePastureEntryMilkPerHour(state, entry, assignedIndex, now, milkOpts);
        const cap = getPastureEntryStockCap(state, entry);
        tickPastureEntryMilk(entry, rate, hours, cap);
        if (!entry.isNarrative && entry.uid !== NARRATIVE_MILTANK_UID) assignedIndex += 1;
    }

    if (state.berryTree) {
        const berryOpts = (masteryOpts?.berryProductionTimeReduction ?? 0) > 0
            ? { productionTimeReduction: masteryOpts!.berryProductionTimeReduction }
            : undefined;
        tickBerryTreeState(state.berryTree, elapsed, now, berryOpts);
    }

    state.lastTickAt = now;
    syncLegacyMilkTotals(state);
    return { pulses: incidentPulses, expiredApproaches, approachesSpawned, spawnedApproaches };
}

export interface MiltankFeedResult {
    ok: boolean;
    reason?: 'no_request' | 'wrong_item' | 'not_enough' | 'too_full';
    level?: number;
    levelUp?: boolean;
    entryLevel?: number;
    entryLevelUp?: boolean;
    farmLevelUp?: boolean;
    xpGained?: number;
}

export function applyMiltankFeed(
    state: MiltankFarmState,
    pastureUid: string,
    itemKey: string,
    now: number,
    _rng: () => number = Math.random,
    feedXpBonus = 0,
): MiltankFeedResult {
    normalizeMiltankFarmState(state);
    const entry = getPastureEntryByUid(state, pastureUid);
    if (!entry) return { ok: false, reason: 'no_request' };

    const req = entry.currentRequest;
    if (!req || req.itemKey !== itemKey) {
        return { ok: false, reason: req ? 'wrong_item' : 'no_request' };
    }

    if (!canFeedEntryBySatiety(entry)) {
        return { ok: false, reason: 'too_full' };
    }

    const def = getMiltankFarmRequestDef(itemKey);
    if (!def) return { ok: false, reason: 'wrong_item' };

    const prevEntryLevel = entry.level;
    const xpGain = getFeedXpForCategory(def.category) + getCareFeedXpBonus(entry)
        + Math.max(0, Math.floor(Number(feedXpBonus) || 0));
    entry.xp = (Number(entry.xp) || 0) + xpGain;
    state.totalFeeds = (Number(state.totalFeeds) || 0) + 1;
    state.feedsTotal = (Number(state.feedsTotal) || 0) + 1;
    syncMiltankFarmProgression(state);
    state.maxAssignableSlots = resolveMaxAssignableSlots(state);

    const catMult = getFeedBoostCategoryMult(def.category);
    entry.productionBoostMult = MILTANK_FARM.feedBoostMult * catMult;
    entry.productionBoostUntil = now + MILTANK_FARM.feedBoostDurationMs * getCareFeedBoostDurationMult(entry);
    addSatietyOnFeed(entry, def.category);

    entry.currentRequest = null;
    ensureMiltankFarmRequestForEntry(entry, entry.level, now, _rng);
    syncLegacyMilkTotals(state);

    const entryLevelUp = entry.level > prevEntryLevel;

    return {
        ok: true,
        level: entry.level,
        levelUp: entryLevelUp,
        entryLevel: entry.level,
        entryLevelUp,
        xpGained: xpGain,
    };
}

export function claimPastureEntryMilk(state: MiltankFarmState, uid: string): number {
    normalizeMiltankFarmState(state);
    const entry = state.pastureEntries?.find((e) => e.uid === uid);
    if (!entry) return 0;
    const stored = Math.max(0, Math.floor(Number(entry.storedMilk) || 0));
    if (stored <= 0) return 0;
    entry.storedMilk = 0;
    state.milkClaimedTotal = (Number(state.milkClaimedTotal) || 0) + stored;
    syncLegacyMilkTotals(state);
    return stored;
}

export function claimMiltankFarmMilk(state: MiltankFarmState, narrativeOnly = false): number {
    normalizeMiltankFarmState(state);
    if (narrativeOnly) {
        return claimPastureEntryMilk(state, NARRATIVE_MILTANK_UID);
    }
    let total = 0;
    for (const entry of state.pastureEntries ?? []) {
        total += claimPastureEntryMilk(state, entry.uid);
    }
    return total;
}

export function getSelectedPastureEntry(state: MiltankFarmState): MiltankPastureEntry | null {
    normalizeMiltankFarmState(state);
    return getPastureEntryByUid(state, state.selectedPastureUid);
}

export function setSelectedPastureUid(state: MiltankFarmState, uid: string): boolean {
    normalizeMiltankFarmState(state);
    if (!state.pastureEntries?.some((e) => e.uid === uid)) return false;
    state.selectedPastureUid = uid;
    return true;
}

export function getPastureEntryByUid(
    state: MiltankFarmState,
    uid: string,
): MiltankPastureEntry | null {
    normalizeMiltankFarmState(state);
    return state.pastureEntries?.find((e) => e.uid === uid) ?? null;
}
