/**
 * Miltank Farm — pasture threats (predators / Team Rocket) and guardian canids.
 */

export type FarmThreatType = 'predator' | 'rocket';

export interface FarmPredatorDef {
    id: string;
    species: string;
    weight: number;
    /** Threat degree 1–100 (higher = harder to repel). */
    threatLevel: number;
}

export interface FarmThreatCombatProfile {
    combatBaseLevel: number;
    combatBaseStatMult: number;
}

const HOUR_MS = 60 * 60 * 1000;

