export function isGuardianSpeciesName(species: string): boolean {
    return GUARDIAN_SPECIES_SET.has(String(species || ''));
}

export function clampThreatLevel(level: number): number {
    return Math.max(1, Math.min(MILTANK_FARM_THREATS.maxThreatLevel, Math.floor(Number(level) || 1)));
}

/** Player-facing intensity (= capped victory count). */
export function getThreatCombatIntensity(threatCombatWins: number): number {
    const raw = Math.max(0, Math.floor(Number(threatCombatWins) || 0));
    return Math.min(MILTANK_FARM_THREATS.threatCombatMaxWins, raw);
}

export function pickWeightedPredator(rng: () => number = Math.random): FarmPredatorDef {
    let total = 0;
    for (const def of PREDATOR_DEFS) total += def.weight;
    let roll = rng() * total;
    for (const def of PREDATOR_DEFS) {
        roll -= def.weight;
        if (roll <= 0) return def;
    }
    return PREDATOR_DEFS[PREDATOR_DEFS.length - 1]!;
}

export function getPredatorCombatBaseProfile(species: string): FarmThreatCombatProfile {
    return PREDATOR_COMBAT_BASE_BY_SPECIES[String(species || '')] ?? DEFAULT_PREDATOR_COMBAT_BASE;
}
